import React, { useState } from "react";
import "./RegistrationForm.css";

const DEPARTMENTS = [
  "Computer Science",
  "Information Technology",
  "Electronics & Communication",
  "Electrical Engineering",
  "Mechanical Engineering",
  "Civil Engineering",
  "Other",
];

export default function RegistrationForm({ onViewParticipants }) {
  const [form, setForm] = useState({ name: "", department: "" });
  const [status, setStatus] = useState("idle"); // idle | loading | success | error
  const [message, setMessage] = useState("");

  const handleChange = (e) => {
    setForm((prev) => ({ ...prev, [e.target.name]: e.target.value }));
  };

  const handleSubmit = async () => {
    const { name, department } = form;
    if (!name.trim() || !department) {
      setStatus("error");
      setMessage("Please fill in all fields.");
      return;
    }

    setStatus("loading");
    try {
      const res = await fetch("http://localhost:5000/register", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ name: name.trim(), department }),
      });
      const data = await res.json();
      if (res.ok) {
        setStatus("success");
        setMessage(data.message || "Registration successful!");
        setForm({ name: "", department: "" });
      } else {
        setStatus("error");
        setMessage(data.error || "Registration failed. Try again.");
      }
    } catch {
      setStatus("error");
      setMessage("Cannot connect to server. Make sure the backend is running.");
    }
  };

  return (
    <div className="card">
      <div className="card-header">
        <p className="card-sub">Already registered? <button className="link-btn" onClick={onViewParticipants}>View list ↗</button></p>
      </div>

      <h2 className="card-title">Create Account</h2>

      <div className="social-row">
        <button className="social-btn google">
          <span className="social-icon">G</span> Sign up with Google
        </button>
        <button className="social-btn facebook">
          <span className="social-icon">f</span> with Facebook
        </button>
      </div>

      <div className="divider"><span>Or sign up using your email address</span></div>

      <div className="field">
        <label htmlFor="name">Name</label>
        <input
          id="name"
          name="name"
          type="text"
          placeholder="Enter your full name"
          value={form.name}
          onChange={handleChange}
          disabled={status === "loading"}
        />
      </div>

      <div className="field">
        <label htmlFor="department">Department</label>
        <select
          id="department"
          name="department"
          value={form.department}
          onChange={handleChange}
          disabled={status === "loading"}
        >
          <option value="">Select your department</option>
          {DEPARTMENTS.map((d) => (
            <option key={d} value={d}>{d}</option>
          ))}
        </select>
      </div>

      {status === "success" && (
        <div className="alert success">
          <span>🚀</span> {message}
          <button className="link-btn" onClick={onViewParticipants}>View participants →</button>
        </div>
      )}

      {status === "error" && (
        <div className="alert error">
          <span>⚠️</span> {message}
        </div>
      )}

      <div className="terms-row">
        <input type="checkbox" id="terms" />
        <label htmlFor="terms">I agree to all terms and Privacy Policy</label>
      </div>

      <button
        className="submit-btn"
        onClick={handleSubmit}
        disabled={status === "loading"}
      >
        {status === "loading" ? (
          <span className="spinner" />
        ) : (
          "Sign up"
        )}
      </button>

      <p className="login-link">
        Already have an account? <button className="link-btn" onClick={onViewParticipants}>Log in</button>
      </p>
    </div>
  );
}
